func schema_pkg_apis_agent_v1alpha1_ClientConfig(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "ClientConfig is the platform's one way to address an external endpoint.\n\nIt embeds Kubernetes admissionregistration.k8s.io/v1 WebhookClientConfig verbatim. URL, Service and CABundle therefore keep their exact JSON shape and semantics: a value can be copied between a platform resource and a ValidatingWebhookConfiguration without translation, and a Kubernetes-native component already knows how to read it.\n\nThe remaining fields are platform extensions. They describe concerns a Kubernetes webhook configuration leaves to its caller (a timeout, a TLS opt-out, static headers and a credential) and never change the meaning of the embedded fields.\n\nURL and Service are mutually exclusive. Service references resolve through the control plane's core/v1 Services; a deployment without that data falls back to the in-cluster DNS name (name.namespace.svc).",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"url": {
						SchemaProps: spec.SchemaProps{
							Description: "url gives the location of the webhook, in standard URL form (`scheme://host:port/path`). Exactly one of `url` or `service` must be specified.\n\nThe `host` should not refer to a service running in the cluster; use the `service` field instead. The host might be resolved via external DNS in some apiservers (e.g., `kube-apiserver` cannot resolve in-cluster DNS as that would be a layering violation). `host` may also be an IP address.\n\nPlease note that using `localhost` or `127.0.0.1` as a `host` is risky unless you take great care to run this webhook on all hosts which run an apiserver which might need to make calls to this webhook. Such installs are likely to be non-portable, i.e., not easy to turn up in a new cluster.\n\nThe scheme must be \"https\"; the URL must begin with \"https://\".\n\nA path is optional, and if present may be any string permissible in a URL. You may use the path to pass an arbitrary string to the webhook, for example, a cluster identifier.\n\nAttempting to use a user or basic auth e.g. \"user:password@\" is not allowed. Fragments (\"#...\") and query parameters (\"?...\") are not allowed, either.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"service": {
						SchemaProps: spec.SchemaProps{
							Description: "service is a reference to the service for this webhook. Either `service` or `url` must be specified.\n\nIf the webhook is running within the cluster, then you should use `service`.",
							Ref:         ref("k8s.io/api/admissionregistration/v1.ServiceReference"),
						},
					},
					"caBundle": {
						SchemaProps: spec.SchemaProps{
							Description: "caBundle is a PEM encoded CA bundle which will be used to validate the webhook's server certificate. If unspecified, system trust roots on the apiserver are used.",
							Type:        []string{"string"},
							Format:      "byte",
						},
					},
					"timeoutSeconds": {
						SchemaProps: spec.SchemaProps{
							Description: "TimeoutSeconds bounds one request. Zero means the caller's default.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"insecureSkipTLSVerify": {
						SchemaProps: spec.SchemaProps{
							Description: "InsecureSkipTLSVerify disables certificate verification. It is strongly discouraged and exists for local development only.",
							Type:        []string{"boolean"},
							Format:      "",
						},
					},
					"headers": {
						SchemaProps: spec.SchemaProps{
							Description: "Headers are sent with every request. A header value may be overridden by the credential resolved from SecretRef/HeadersRef.",
							Type:        []string{"object"},
							AdditionalProperties: &spec.SchemaOrBool{
								Allows: true,
								Schema: &spec.Schema{
									SchemaProps: spec.SchemaProps{
										Type:   []string{"string"},
										Format: "",
									},
								},
							},
						},
					},
					"secretRef": {
						SchemaProps: spec.SchemaProps{
							Description: "SecretRef resolves one credential key from a Secret. The value is sent as a bearer token. It is mutually exclusive with HeadersRef.",
							Ref:         ref("k8s.io/api/core/v1.SecretKeySelector"),
						},
					},
					"headersRef": {
						SchemaProps: spec.SchemaProps{
							Description: "HeadersRef imports every key of a Secret as a request header. It is mutually exclusive with SecretRef.",
							Ref:         ref("k8s.io/api/core/v1.LocalObjectReference"),
						},
					},
				},
			},
		},
		Dependencies: []string{
			"k8s.io/api/admissionregistration/v1.ServiceReference", "k8s.io/api/core/v1.LocalObjectReference", "k8s.io/api/core/v1.SecretKeySelector"},
	}
}

